-- Subconjunto das tabelas do neto_rioverde usadas pela ponte (tipos texto como no MySQL)
CREATE TABLE s_cad_aluno (COD_ALU INTEGER PRIMARY KEY, COD_TUR TEXT, NOM_ALU TEXT, CPF_ALU TEXT, CPF_RES TEXT, NOM_PAI_ALU TEXT,
  WHATS TEXT, CEL_ALU TEXT, FON_ALU TEXT, TEL_RESP TEXT, FON_PAI_ALU TEXT, EMAIL_ALU TEXT, CIT_ATU_ALU TEXT, DAT_NAS_ALU TEXT);
CREATE TABLE s_cad_matricula (COD_MATRICULA TEXT, COD_ALU TEXT, NOM_CUR TEXT, COD_TUR TEXT, STATUS_MAT TEXT, DAT_VENC TEXT);
CREATE TABLE s_cad_turma (ID_TUR INTEGER PRIMARY KEY, COD_TUR TEXT, COD_CUR TEXT);
CREATE TABLE s_cad_curso (ID_CUR INTEGER PRIMARY KEY, COD_CUR TEXT, NOM_CUR TEXT);
CREATE TABLE s_cad_parcela (COD_PAR INTEGER PRIMARY KEY, COD_ALU TEXT, DAT_LAN TEXT, DAT_VEN TEXT, DAT_BAI TEXT, VLR_PAR TEXT,
  TIP_PAR TEXT, TIPO_PAR TEXT NOT NULL DEFAULT '', VLR_COB TEXT, VLR_DES TEXT, NUM_BOLETO TEXT NOT NULL DEFAULT '',
  NUM_MATRICULA TEXT NOT NULL DEFAULT '', COD_BARRA TEXT NOT NULL DEFAULT '');
CREATE TABLE contabil (CODI_CON INTEGER PRIMARY KEY AUTOINCREMENT, DATA_LAN TEXT, CODI_FOR TEXT, CODI_TIPO_LAN TEXT, DESC_CON TEXT,
  DEBI_CRED TEXT, VLR_CON TEXT, CODI_USU TEXT, COD_FIN TEXT);
CREATE TABLE f_cad_saldo (ID INTEGER PRIMARY KEY AUTOINCREMENT, TIPO TEXT, VALOR TEXT);
CREATE TABLE s_cad_ocorrencia (COD_OCO INTEGER PRIMARY KEY AUTOINCREMENT, COD_ALU TEXT, DAT_OCO TEXT, HOR_OCO TEXT, OCO_OCO TEXT,
  PRO_OCO TEXT, NOM_ALU TEXT, MATRICULA_OCO TEXT, TURMA_OCO TEXT, STATUS_ANT_OCO TEXT, STATUS_OCO TEXT, ID_REP TEXT, DAT_FALT TEXT);
CREATE TABLE s_cad_agend_pag (ID INTEGER PRIMARY KEY AUTOINCREMENT, COD_ALU INTEGER, NOM_ALU TEXT, DAT_VENC TEXT, DAT_PAG TEXT,
  COD_MATRICULA TEXT, PAGO TEXT, RESP INTEGER NOT NULL);
CREATE TABLE historico_carta (COD_HIST INTEGER PRIMARY KEY AUTOINCREMENT, COD_CART INTEGER, COD_ALU INTEGER, NOM_CART TEXT, DAT_EMIT TEXT, STATUS_CART TEXT);
CREATE TABLE s_cad_carta (COD_CAR INTEGER PRIMARY KEY, TIPO TEXT, DESC_CAR TEXT);
CREATE TABLE s_cad_pres_aluno (ID_PRES_ALU INTEGER PRIMARY KEY AUTOINCREMENT, COD_ALU TEXT, NOM_ALU TEXT, FAL_PRE TEXT, DAT_FAL TEXT,
  COD_TUR TEXT, COD_MATRICULA_PRES TEXT);
CREATE TABLE franquia (ID_franquia INTEGER PRIMARY KEY, Empresa TEXT, razao_social TEXT, CNPJ_EMP TEXT);
